<content>
1: # 苏住房防汛C端（uni-app H5）本地 nginx 部署
2: # 构建产物：D:/repository/苏住房防汛C端/dist（npm run test / uni build -m test --outDir ./dist）
3: # 由 nginx.conf 的 include conf.d/*.conf 自动加载，无需改动主配置。
4: #
5: # 端口说明：原用 8103 + default_server，与 sites-enabled/昆山物管.conf（昆山G，
6: # listen 8103 server_name localhost）抢占，且 default_server 会让所有其它 Host
7: # 的 8103 请求都落到本服务上，影响昆山项目。故改到空闲端口 8095 并去掉 default_server。
8: server {
9:     listen 8095;
10:     server_name localhost;
11:     root "D:/repository/苏住房防汛C端/dist";
12:     index index.html;
13:     charset utf-8;
14: 
15:     # 静态资源长缓存，index.html 强制不走缓存，避免发版后 chunk 404
16:     location ~* \.(js|css|png|jpg|jpeg|gif|ico|svg|woff|woff2|ttf|eot|map)$ {
17:         expires 7d;
18:         add_header Cache-Control "public" always;
19:         access_log off;
20:         try_files $uri =404;
21:     }
22: 
23:     location = /index.html {
24:         expires -1;
25:         add_header Cache-Control "no-cache, no-store, must-revalidate";
26:     }
27: 
28:     # 反向代理：/api/ 转发苏住房 dev 网关（含登录 /v2.0/code、/v2.0/security/auth/login）
29:     location /api/ {
30:         proxy_pass http://unlimited.c.h5.query.mobile.v2.suzhufang.shiqu.suzhou.dev.zhi.com;
31:         proxy_http_version 1.1;
32:         proxy_set_header Host unlimited.c.h5.query.mobile.v2.suzhufang.shiqu.suzhou.dev.zhi.com;
33:         proxy_set_header X-Real-IP $remote_addr;
34:         proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
35:         proxy_set_header X-Forwarded-Proto $scheme;
36:     }
37: 
38:     # uni-app H5 使用 hash 路由，回退到 index.html 即可
39:     location / {
40:         try_files $uri $uri/ /index.html;
41:     }
42: }

